import logging
import traceback
from datetime import datetime

# 配置日志记录器
logging.basicConfig(
    level=logging.ERROR,
    format='%(asctime)s - %(name)s - %(levelname)s - [上下文变量: %(context)s] - %(message)s',
    datefmt='%Y-%m-%d %H:%M:%S'
)
logger = logging.getLogger(__name__)

class ContextFilter(logging.Filter):
    """日志过滤器，用于添加上下文变量"""
    def __init__(self, context_vars=None):
        super().__init__()
        self.context_vars = context_vars or {}

    def filter(self, record):
        record.context = str(self.context_vars)
        return True

# 添加上下文过滤器
context_filter = ContextFilter()
logger.addFilter(context_filter)

def helper(x, **kwargs):
    """带错误日志记录的helper函数"""
    context_vars = {
        'x': x,
        'kwargs': kwargs,
        'function': 'helper'
    }
    context_filter.context_vars = context_vars

    try:
        return x * 2
    except Exception as e:
        error_type = type(e).__name__
        stack_info = traceback.format_exc()

        logger.error(
            f"错误类型: {error_type} | "
            f"错误信息: {str(e)} | "
            f"调用栈:\n{stack_info}"
        )
        raise

